frappe.listview_settings['Attendance Request'] = {
    get_indicator: function (doc) {
        const map = {
            'Late \u226415 min': 'yellow',
            'Late 15-30 min': 'orange',
            'Late 30-60 min': 'purple',
            'Late 1-2 hr': 'pink',
            'Late >2 hr': 'red'
        };
        if (doc.custom_late_category && map[doc.custom_late_category]) {
            return [__(doc.custom_late_category), map[doc.custom_late_category], 'custom_late_category,=,' + doc.custom_late_category];
        }
        if (doc.docstatus === 1) return [__('Approved'), 'green', 'docstatus,=,1'];
        return [__('Pending'), 'grey', 'docstatus,=,0'];
    }
};

frappe.ui.form.on('Logikview Appraisal', {
    employee(frm) {
        // pull the parameter set + reviewer chain as soon as an employee is chosen,
        // so a hand-created appraisal looks exactly like an auto-generated one
        if (!frm.doc.employee) return;
        frappe.call({
            method: 'logikview_hr.appraisal.resolve_defaults',
            args: { employee: frm.doc.employee },
            callback: (r) => {
                const d = r.message;
                if (!d) return;
                ['assessment_type', 'reporting_officer', 'first_director',
                 'second_director', 'cc_director', 'needs_second_director'].forEach(f => {
                    if (!frm.doc[f]) frm.set_value(f, d[f]);
                });
                if (!(frm.doc.ratings || []).length && (d.ratings || []).length) {
                    frm.clear_table('ratings');
                    d.ratings.forEach(row => {
                        const c = frm.add_child('ratings');
                        c.category = row.category;
                        c.parameter = row.parameter;
                    });
                    frm.refresh_field('ratings');
                }
            }
        });
    },

    refresh(frm) {
        const me = frappe.session.user;
        const st = frm.doc.workflow_state;
        const isEmp = me === frm.doc.employee_user;
        const isRO  = me === frm.doc.ro_user;
        const isD1  = me === frm.doc.first_director_user;
        const isD2  = me === frm.doc.second_director_user;
        const isHR  = frappe.user.has_role('HR Manager') || frappe.user.has_role('System Manager');

        const empEdit = (!st || st === 'Pending Self-Assessment') && (isEmp || isHR);
        const roEdit  = (st === 'Pending Manager Review')   && (isRO  || isHR);
        const d1Edit  = (st === 'Pending Director Review')  && (isD1  || isHR);
        const d2Edit  = (st === 'Pending Final Director')   && (isD2  || isHR);

        // the parameter list is fixed: no adding, no deleting, no editing the text
        const grid = frm.fields_dict.ratings.grid;
        grid.cannot_add_rows = true;
        if (grid.df) { grid.df.cannot_add_rows = true; }
        grid.update_docfield_property('category',  'read_only', 1);
        grid.update_docfield_property('parameter', 'read_only', 1);
        grid.update_docfield_property('employee_rating', 'read_only', empEdit ? 0 : 1);
        grid.update_docfield_property('ro_rating',       'read_only', roEdit  ? 0 : 1);
        frm.refresh_field('ratings');
        if (grid.wrapper) {
            grid.wrapper.find('.grid-add-row, .grid-remove-rows, .grid-remove-all-rows').hide();
        }

        // narratives (employee)
        ['q_accomplishments', 'q_not_accomplished', 'q_goals'].forEach(f =>
            frm.set_df_property(f, 'read_only', empEdit ? 0 : 1));

        // director feedback
        frm.set_df_property('first_director_feedback',  'read_only', d1Edit ? 0 : 1);
        frm.set_df_property('second_director_feedback', 'read_only', d2Edit ? 0 : 1);

        const hint = {
            'Pending Self-Assessment': 'Employee to fill the self-assessment (Your Rating + the three questions).',
            'Pending Manager Review':  'Reporting officer to fill the RO Rating column.',
            'Pending Director Review': 'Director to add their feedback comment.',
            'Pending Final Director':  'Final director to add closing feedback.',
            'Completed':               'Appraisal completed.'
        }[st];
        if (hint) frm.dashboard.set_headline(hint);
    }
});

frappe.ui.form.on('Fun Friday Idea', {
    refresh(frm) {
        if (frm.is_new()) return;
        const me = frappe.session.user;
        const liked = (frm.doc.votes || []).some(v => v.user === me);
        frm.add_custom_button(liked ? '\u2665 Liked (' + (frm.doc.vote_count || 0) + ')'
                                    : '\u2661 Like (' + (frm.doc.vote_count || 0) + ')', () => {
            frappe.call({
                method: 'logikview_hr.logikview_hr.doctype.fun_friday_idea.fun_friday_idea.toggle_like',
                args: { idea: frm.doc.name },
                callback: () => frm.reload_doc()
            });
        });
        frm.dashboard.set_headline(
            'Fun Friday is every Friday, 5:00 - 6:00 PM. Add your idea and like the ones you want to do!'
        );
    }
});

frappe.listview_settings['Fun Friday Idea'] = {
    add_fields: ['status', 'vote_count'],
    get_indicator: function (doc) {
        const map = { 'Proposed': 'blue', 'Shortlisted': 'orange', 'Scheduled': 'purple', 'Done': 'green' };
        return [__(doc.status) + ' \u00b7 \u2665 ' + (doc.vote_count || 0),
                map[doc.status] || 'grey', 'status,=,' + doc.status];
    }
};
